{
  "code": "600519",
  "rebuttals": [
    {
      "target": "methods[0].assumptions.dividend_growth",
      "attack": "DDM假设长期股利增速3%，但估值方自己披露2025年营收1720.54亿元低于2024年1741.44亿元，2025年净利润823.20亿元低于2024年862.28亿元，2026H1净利润同比再降约1.95%。在盈利连续收缩、分红率已高达75%-80%的情况下，3%永续股利增长需要净利润同步增长，否则只能继续提高分红率或减少留存，不可持续。该假设与已披露盈利趋势冲突。",
      "severity": "high"
    },
    {
      "target": "methods[0].assumptions.ttm_dps_cny",
      "attack": "TTM股利51.98元仅取2025-12-19（23.957元）和2026-06-26（28.024元）两次支付，未明确是否完整覆盖最近12个月现金分红，也未说明是否遗漏2025-06-26等相邻支付。若最近12个月实际DPS口径不同，DDM起始点将出现偏差；且51.98元对应分红率约79%，处于历史高位，不宜作为永续增长基线。",
      "severity": "medium"
    },
    {
      "target": "methods[0].assumptions.cost_of_equity",
      "attack": "DDM使用8%权益成本，但未给出无风险利率、ERP和beta；当前PE_TTM为20.37、历史分位0.796，显示市场风险偏好并未给茅台很低的折现率。若权益成本上行至9%以上，1071元价值将显著下降，DDM结论对折现率极敏感。",
      "severity": "medium"
    },
    {
      "target": "methods[1].assumptions.normalized_fcf_cny_m",
      "attack": "归一化FCF 750亿元缺少严格计算过程。2024年FCF 877.85亿元、2025年583.95亿元、2026H1 698.59亿元，三年波动剧烈，估值方未说明波动来自经营现金流、营运资本、合同负债还是资本开支。2026H1 FCF已接近2025全年，若简单不年化，则隐含2026全年仅750亿元、下半年不足60亿元，与上半年数据形成内部矛盾；若上半年存在一次性释放，750亿元又可能偏高。",
      "severity": "high"
    },
    {
      "target": "methods[1].assumptions.shares_m",
      "attack": "用2026H1净利润44,516,880,421.86元与EPS 35.57元倒推股本约12.52亿股，但EPS可能是加权平均股数而非期末股数，且若有回购/库存股、少数股东损益差异，该倒推口径可能失真。应使用期末总股本、加权股数和扣除少数股东权益后的归母口径分别校验。",
      "severity": "low"
    },
    {
      "target": "methods[1].assumptions.cost_of_equity",
      "attack": "FCF DCF使用8.5%权益成本、3%永续增长，终值占比极高。仅将权益成本上调至9.5%、终端增速下调至2%，权益价值约750/(0.095-0.02)=10000亿元，对应每股约799元，较1089元下降约27%。估值方未提供敏感性，内在价值下限并不可靠。",
      "severity": "high"
    },
    {
      "target": "methods[2].assumptions.normalized_eps_cny",
      "attack": "以2025年EPS 65.66元作为穿越周期盈利中枢缺乏依据。2025年营收、净利润均同比下滑，2026H1净利润继续下降约1.95%，且毛利率从91.93%降至89.56%，均表明当前可能仍处下行期而非中枢。若2026年全年延续上半年的下降趋势，EPS可能低于65.66元；把2025年单年盈利作为中枢会高估PE法价值。",
      "severity": "high"
    },
    {
      "target": "methods[2].assumptions.fair_pe",
      "attack": "公平PE 21.17倍高于当前PE_TTM 20.37倍，但估值方同时承认历史PE分位0.796偏高、低增长和政策风险。盈利负增长叠加历史估值高分位时，市场通常不会给估值扩张；ROE 32.53%和毛利率91.18%是历史结果，边际已走弱。21.17倍更像乐观情形，合理PE若降至17-18倍，PE法内在价值将显著低于1390元。",
      "severity": "high"
    },
    {
      "target": "moat_evidence[0]",
      "attack": "毛利率“保持高位”的表述忽略连续下滑：2024年91.93%、2025年91.18%、2026H1 89.56%，两年半累计下降2.37个百分点，2026H1已跌破90%。若品牌定价权极强，毛利率不应连续下行；该趋势可能反映产品结构降级、系列酒占比上升或渠道价格压力，削弱宽护城河证据。",
      "severity": "medium"
    },
    {
      "target": "moat_evidence[1]",
      "attack": "2025年FCF/净利润约71%，但2024年为877.85/862.28约101.8%，一年下降约30个百分点。FCF转化率剧烈波动说明“股东回报能力极强”不能仅凭2025年单年数据；若FCF下降来自营运资金或基酒库存占用，实际可用于回报股东的现金质量低于表面。",
      "severity": "medium"
    },
    {
      "target": "moat_evidence[2]",
      "attack": "连续大额分红是事实，但估值方未检查特别分红是否与集团关联方资金需求有关；75%-80%分红率在盈利下滑期可能表明缺乏再投资机会，呈现价值陷阱特征。若关联交易向集团倾斜，高分红未必等于小股东回报质量。",
      "severity": "medium"
    },
    {
      "target": "margin_of_safety",
      "attack": "安全边际-0.238与现价和区间不一致：按现价1325元和下限1070元，标准口径(1070-1325)/1325应为约-19.2%；-0.238更像以1070为分母计算。若使用标准安全边际口径，结论会变化，可能误导决策。",
      "severity": "medium"
    },
    {
      "target": "intrinsic_value_range",
      "attack": "区间上沿1390元几乎完全由PE法的21.17倍公平PE贡献，而DDM和FCF DCF两个方法分别仅1071元和1089元、均低于现价1325元。剔除或下调该PE法假设后，内在价值区间将整体低于现价。估值方将乐观PE情形纳入区间可能掩盖当前价格无安全边际的事实。",
      "severity": "high"
    }
  ],
  "fatal_issues": [
    "PE法使用2025年EPS和21.17倍公平PE，高于当前PE_TTM 20.37倍，与自身“低增长、历史估值分位偏高”的判断冲突，可能系统性拉高内在价值上限。",
    "DDM和FCF DCF均给出约1070-1089元、低于现价1325元，只有PE法给出1390元；如果盈利中枢和公平PE假设被证伪，当前价格没有任何安全边际。",
    "估值方未检查合同负债/预收款、渠道库存、系列酒占比及集团关联交易等利润质量问题，可能漏掉真实动销和归母利润被摊薄的风险。"
  ],
  "verdict": "整体来看，估值方的低情景DDM/FCF相对克制，但PE法使用2025年EPS和21.17倍公平PE明显乐观，且与盈利下滑、历史PE分位偏高的风险披露相矛盾；毛利率连续下滑和高分红率提示存在价值陷阱风险。当前价1325元高于两个现金流口径的内在价值，安全边际依赖乐观PE假设，逻辑不够稳健。",
  "needs_data": [
    "2025年与2026年合同负债/预收款项变化及渠道库存、批价/出厂价数据",
    "2024-2026年FCF详细计算表：经营现金流净额、资本开支、营运资金变动",
    "2025年度利润分配方案全文及是否包含特别分红、中期分红",
    "股本明细：期末总股本、加权平均股数、库存股/回购数量",
    "关联交易详情：茅台集团营销公司及少数股东损益对归母利润的影响",
    "PE历史分位对应的利率、盈利周期及行业估值区间"
  ]
}
